import axios from "axios";
import { MDBDataTable } from "mdbreact";
import MUIDataTable, { CustomToolbarSelect } from "mui-datatables";
import MaterialTable from "material-table";
import React, { Component } from "react";
import {
  MdAddCircle,
  MdCheckCircle,
  MdEdit,
  MdRemoveCircle
} from "react-icons/md";
import { connect } from "react-redux";
import { Button, Card, CardBody, CardHeader, Input, Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";

class Clients extends Component {
  state = {
    addRow: false,
    rowData: [],
    clientsLoaded: false,
    newClientName: "",
    editRow: false,
    editRowIndex: 0,
    editClientName: ""
  };

  componentDidMount() {
    this.retrieveClients();
  }

  addRow = () => {
    const aR = this.state.rowData;
    if (!this.state.addRow) {
      aR.unshift({
        id: "Auto",
        name: (
          <Input
            type="text"
            id="NCN"
            name="newClientName" //has to match the name of the variable in the state
            placeholder="Client Name"
            onChange={this.onChange}
          ></Input>
        ),
        created_by: this.props.auth.isAuthenticated
          ? this.props.auth.user.name
          : "Guest",
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.addClient}
            >
              <MdCheckCircle />
            </Button>
          </div>
        )
      });
    } else {
      aR.splice(0, 1);
    }
    this.setState(state => ({
      addRow: !state.addRow,
      rowData: aR,
      clientsLoaded: state.clientsLoaded,
      newClientName: state.newClientName
    }));
  };

  retrieveClients = () => {
    console.log("loading");
    this.setState(state => ({
      addRow: state.addRow,
      clientsLoaded: false,
      rowData: state.rowData,
      newClientName: state.newClientName
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name,
            created_by: x.createdByUserId.name,
            actions: (
              <div>
                <Button
                  className="float-left"
                  color="dark"
                  onClick={this.editRow.bind(this, index)}
                >
                  <MdEdit />
                </Button>
                <Button
                  className="float-left ml-1"
                  color="dark"
                  onClick={this.removeClient.bind(this, x._id)}
                >
                  <MdRemoveCircle />
                </Button>
              </div>
            )
          };
        });

        this.setState(state => ({
          addRow: state.addRow,
          clientsLoaded: true,
          rowData,
          newClientName: state.newClientName
        }));
      })
      .catch(err => console.log(err));
  };

  addClient = () => {
    const newClient = {
      name: this.state.newClientName,
      userId: this.props.auth.isAuthenticated
        ? this.props.auth.user._id
        : "Guest"
    };
    axios
      .post("/api/clients", newClient, tokenConfig(store.getState))
      .then(res => {
        console.log(res.data);
        this.addRow();
        this.retrieveClients();
      })
      .catch(err => console.log(err.data));
  };

  editRow = index => {
    const rowData1 = this.state.rowData;
    rowData1[index] = {
      id: this.state.rowData[index].id,
      name: (
        <Input
          type="text"
          name="editClientName" //has to match the name of the variable in the state
          placeholder={this.state.rowData[index].name}
          onChange={this.onChange}
        ></Input>
      ),
      created_by: this.state.rowData[index].id,
      actions: (
        <div>
          <Button
            className="float-left"
            color="dark"
            onClick={this.editRow.bind(this, index)}
          >
            <MdEdit />
          </Button>
          <Button
            className="float-left ml-1"
            color="dark"
            onClick={this.removeClient.bind(this, this.state.rowData[index].id)}
          >
            <MdRemoveCircle />
          </Button>
        </div>
      )
    };

    this.setState(state => ({
      addRow: state.addRow,
      clientsLoaded: true,
      rowData: rowData1,
      newClientName: state.newClientName,
      editRow: !state.editRow,
      editRowIndex: index
    }));
    console.log(this.state.editRowIndex);
  };

  editClient = id => {
    //console.log(id);
    /*
    const modifiedClient = {
      name: "kjhkhkhkj",
      userId: this.props.auth.isAuthenticated
        ? this.props.auth.user._id
        : "Guest"
    };
    axios
      .put(`/api/clients/${id}`, modifiedClient, tokenConfig(store.getState))
      .then(res => {
        console.log(res.data);
        this.retrieveClients();
      })
      .catch(err => console.log(err.data));*/
  };

  removeClient = id => {
    axios
      .delete(`/api/clients/${id}`, tokenConfig(store.getState))
      .then(res => {
        console.log(res.data);
        this.retrieveClients();
      })
      .catch(err => console.log(err.data));
  };

  onChange = e => {
    this.setState({ [e.target.name]: e.target.value });
  };
  render() {
    return (
      <Card>
        <CardHeader>
          <h4 className="float-left">Clients</h4>
          <Button className="float-right" color="dark" onClick={this.addRow}>
            <MdAddCircle />
          </Button>
        </CardHeader>
        <CardBody>
          {this.state.clientsLoaded ? (
            <MaterialTable
              columns={[
                { title: "ID", field: "id" },
                { title: "Name", field: "name" },
                { title: "Created By", field: "created_by" },
                { title: "Actions", field: "actions" }
              ]}
              data={this.state.rowData}
              title=""
            />
          ) : (
            <div
              style={{
                display: "flex",
                justifyContent: "center"
              }}
            >
              <Spinner animation="border" />
            </div>
          )}
        </CardBody>
      </Card>
    );
  }
}

const mapStateToProps = state => ({
  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

//export default connect(mapStateToProps, {postClient,getClients,deleteClient})(Clients);
export default connect(mapStateToProps, null)(Clients);
